/**
 * uplot-shim.js — lightweight Canvas2D chart compatible with our app.js uPlot API subset.
 * Zero dependencies. Works fully offline. Implements only the methods we use:
 *   new uPlot(opts, data, container) → plot
 *   plot.setData(data)
 *   plot.setSize({width, height})
 *   plot.valToPos(val, axis)
 *
 * Data format: [ timestamps_array, series1_array, series2_array, ... ]
 * Series format: opts.series = [{}, {label, stroke, width, fill}, ...]
 */
(function (global) {
  'use strict';

  const PAD = { top: 10, right: 20, bottom: 32, left: 60 };

  class uPlot {
    constructor(opts, data, container) {
      this.opts = opts;
      this.data = data || [[], []];
      this.width  = opts.width  || container.clientWidth  || 400;
      this.height = opts.height || 200;

      this.canvas = document.createElement('canvas');
      this.canvas.style.cssText = 'display:block;width:100%;max-width:100%;';
      this.ctx = this.canvas.getContext('2d');
      container.appendChild(this.canvas);

      this.markers = [];
      this.regions = [];

      this._updateSize();
      this._draw();
    }

    setData(data) {
      this.data = data;
      this._draw();
    }

    setMarkers(markers) {
      this.markers = markers || [];
      this._draw();
    }

    setRegions(regions) {
      this.regions = regions || [];
      this._draw();
    }

    setSize({ width, height }) {
      if (width)  this.width  = width;
      if (height) this.height = height;
      this._updateSize();
      this._draw();
    }

    /** Convert a data value to canvas pixel position */
    valToPos(val, axis) {
      const xs = this.data[0];
      if (!xs || xs.length < 2) return 0;
      const xMin = xs[0], xMax = xs[xs.length - 1];
      const plotW = this.width  - PAD.left - PAD.right;
      return PAD.left + ((val - xMin) / (xMax - xMin || 1)) * plotW;
    }

    _updateSize() {
      const dpr = window.devicePixelRatio || 1;
      this.canvas.width  = Math.round(this.width  * dpr);
      this.canvas.height = Math.round(this.height * dpr);
      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    _draw() {
      const { ctx, width, height, data, opts } = this;
      ctx.clearRect(0, 0, width, height);

      const xs = data[0];
      if (!xs || xs.length < 2) {
        this._drawEmpty();
        return;
      }

      const plotW = width  - PAD.left - PAD.right;
      const plotH = height - PAD.top  - PAD.bottom;
      const xMin = xs[0], xMax = xs[xs.length - 1];
      const xRange = xMax - xMin || 1;

      // Collect all y-values to find range
      let yMin = Infinity, yMax = -Infinity;
      for (let si = 1; si < data.length; si++) {
        (data[si] || []).forEach(v => {
          if (v != null && isFinite(v)) { yMin = Math.min(yMin, v); yMax = Math.max(yMax, v); }
        });
      }
      if (!isFinite(yMin)) { yMin = 0; yMax = 1; }
      const yPad = (yMax - yMin) * 0.1 || 0.1;
      yMin -= yPad; yMax += yPad;
      const yRange = yMax - yMin;

      const xPos = (x)  => PAD.left + ((x - xMin) / xRange) * plotW;
      const yPos = (y)  => PAD.top  + (1 - (y - yMin) / yRange) * plotH;

      // Background
      ctx.fillStyle = '#161b22';
      ctx.fillRect(PAD.left, PAD.top, plotW, plotH);

      // Grid lines
      ctx.strokeStyle = '#21262d';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = PAD.top + (plotH / 4) * i;
        ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + plotW, y); ctx.stroke();
      }

      // Shaded anomaly injection regions
      if (this.regions && this.regions.length > 0) {
        for (const reg of this.regions) {
          const x0 = xPos(reg.start);
          const x1 = reg.end ? xPos(reg.end) : (PAD.left + plotW);
          if (x1 < PAD.left || x0 > PAD.left + plotW) continue;
          const left = Math.max(PAD.left, Math.min(x0, x1));
          const right = Math.min(PAD.left + plotW, Math.max(x0, x1));
          ctx.fillStyle = reg.color || 'rgba(204, 121, 167, 0.22)';
          ctx.fillRect(left, PAD.top, Math.max(3, right - left), plotH);
        }
      }

      // Fill between series 2 (expected) and series 1 (actual) if 2 series exist
      if (data.length >= 3 && data[2] && data[2].length === xs.length) {
        ctx.beginPath();
        ctx.moveTo(xPos(xs[0]), yPos(data[1][0]));
        for (let i = 1; i < xs.length; i++) ctx.lineTo(xPos(xs[i]), yPos(data[1][i] ?? data[1][i-1]));
        for (let i = xs.length - 1; i >= 0; i--) ctx.lineTo(xPos(xs[i]), yPos(data[2][i] ?? data[2][i+1] ?? 0));
        ctx.closePath();
        ctx.fillStyle = 'rgba(88,166,255,0.1)';
        ctx.fill();
      }

      // Series lines
      for (let si = 1; si < data.length && si < (opts.series?.length || 10); si++) {
        const ys = data[si];
        if (!ys || ys.length === 0) continue;
        const seriesOpts = opts.series?.[si] || {};
        ctx.strokeStyle = seriesOpts.stroke || '#58a6ff';
        ctx.lineWidth   = seriesOpts.width  || 1.5;
        ctx.lineJoin    = 'round';
        ctx.lineCap     = 'round';
        if (si > 1) {
          ctx.setLineDash([4, 4]);
        } else {
          ctx.setLineDash([]);
        }
        ctx.beginPath();
        let started = false;
        for (let i = 0; i < xs.length; i++) {
          const y = ys[i];
          if (y == null || !isFinite(y)) continue;
          if (!started) { ctx.moveTo(xPos(xs[i]), yPos(y)); started = true; }
          else ctx.lineTo(xPos(xs[i]), yPos(y));
        }
        ctx.stroke();
        ctx.setLineDash([]);
      }

      // Anomaly markers (circles)
      if (this.markers && this.markers.length > 0) {
        for (const m of this.markers) {
          if (m.ts < xMin || m.ts > xMax) continue;
          const x = xPos(m.ts);
          ctx.beginPath();
          ctx.arc(x, PAD.top + 10, 4.5, 0, Math.PI * 2);
          ctx.fillStyle = m.color || '#FF5252';
          ctx.fill();
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }
      }

      // X-axis labels (time)
      ctx.fillStyle = '#8b949e';
      ctx.font = '10px Consolas,monospace';
      ctx.textAlign = 'center';
      const labelCount = Math.min(6, xs.length);
      for (let i = 0; i < labelCount; i++) {
        const idx = Math.round((xs.length - 1) * i / Math.max(1, labelCount - 1));
        const ts  = xs[idx];
        const lbl = ts ? new Date(ts * 1000).toISOString().slice(11, 16) : '';
        ctx.fillText(lbl, xPos(ts), height - 8);
      }

      // Y-axis labels
      ctx.textAlign = 'right';
      for (let i = 0; i <= 4; i++) {
        const v = yMin + (yRange / 4) * (4 - i);
        const lbl = '$' + (v >= 1 ? v.toFixed(2) : v.toFixed(5));
        ctx.fillText(lbl, PAD.left - 4, PAD.top + (plotH / 4) * i + 4);
      }

      // Border
      ctx.strokeStyle = '#30363d';
      ctx.lineWidth = 1;
      ctx.strokeRect(PAD.left, PAD.top, plotW, plotH);
    }

    _drawEmpty() {
      const { ctx, width, height } = this;
      ctx.fillStyle = '#161b22';
      ctx.fillRect(PAD.left, PAD.top, width - PAD.left - PAD.right, height - PAD.top - PAD.bottom);
      ctx.fillStyle = '#8b949e';
      ctx.font = '12px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText('Waiting for data…', width / 2, height / 2);
    }
  }

  global.uPlot = uPlot;
})(window);

